<?php $cart=$page['cart'];$cartId=(int)$cart['account']['id'];$preview=$page['preview']??false;$editable=$preview?(permissionHas('restaurante.accounts','create')&&permissionHas('restaurante.accounts','edit')):($cart['account']['status']==='open'&&permissionRecord('restaurante.accounts',$cartId,'edit')); ?>
<section class="restaurant-pos" data-pos-root data-pos-version="<?= (int)$cart['account']['version'] ?>">
<div class="restaurant-pos-catalog restaurant-panel"><div class="restaurant-pos-catalog-head"><div><p class="eyebrow">CARTA</p><h2>Selecciona los productos</h2></div><a class="button" href="index.php">← Mesas</a></div>
<label class="restaurant-pos-search"><span class="visually-hidden">Buscar producto</span><input type="search" data-pos-search placeholder="Buscar producto…" autocomplete="off"></label>
<?php require __DIR__.'/categories.php'; ?>
<div class="restaurant-pos-products"><?php foreach($page['products'] as $product): ?><form method="post" <?= $preview?'': 'data-pos-command' ?> data-pos-product data-pos-name="<?= $h(mb_strtolower($product['name'])) ?>" data-pos-category-id="<?= (int)$product['category_id'] ?>"><?php restaurantPosFields($cart,$preview?'save_first_product':'pos_add'); ?><?php if($preview): ?><input type="hidden" name="table_id" value="<?= (int)$page['table']['id'] ?>"><input type="hidden" name="table_version" value="<?= (int)$page['table']['version'] ?>"><?php endif; ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><button type="submit" <?= !$editable||!$product['available']?'disabled':'' ?>><span class="restaurant-pos-product-icon" aria-hidden="true"><?= $h(mb_substr($product['name'],0,1)) ?></span><strong><?= $h($product['name']) ?></strong><span><?= $product['available']?$h($product['display_price'].' '.$cart['currency']):'Requiere tasa' ?></span><?php if($editable): ?><b aria-hidden="true">＋</b><?php endif; ?></button></form><?php endforeach; ?></div>
<?php if(!$page['products']): ?><p class="restaurant-empty"><?= empty($page['restaurantCategoryIds'])?'Marca «Es para restaurante» en las categorías principales de Inventario para mostrar sus productos aquí.':'No hay productos habilitados para venta en las categorías de restaurante.' ?></p><?php endif; ?><p class="restaurant-empty" data-pos-no-results hidden>No se encontraron productos.</p>
</div>
<aside class="restaurant-panel restaurant-pos-ticket" aria-label="Pedido de la mesa"><p class="restaurant-error" data-pos-error role="alert" hidden></p><p class="restaurant-pos-saving" data-pos-saving role="status" hidden>Guardando…</p><div data-pos-cart><?php require __DIR__.'/cart.php'; ?></div></aside>
<?php if(isset($page['clients'])&&$cart['account']['status']==='open'): ?>
<?php require __DIR__.'/checkout.php'; ?>
<?php endif; ?></section>
